{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","i":"Writing CLI argument parser","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Parses the census CLI's positional syntax:
/// <c>census &lt;trace.jsonl&gt;</c> and <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.
/// Anything else yields an empty dictionary, which the runner turns into usage + exit 1.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Maps the CLI arguments onto <see cref="AutoWrongCensusOptions"/> configuration keys.</summary>
	/// <param name="args">Raw CLI arguments (without the executable name).</param>
	/// <returns>Configuration key/value pairs; empty when the invocation is not a census or pairs command.</returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase) && args.Length == 2)
		{
			dict[Key("Command")] = "census";
			dict[Key("TracePath")] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase) && args.Length == 3)
		{
			dict[Key("Command")] = "pairs";
			dict[Key("CensusTsvPath")] = args[1];
			dict[Key("TracePath")] = args[2];
		}

		return dict;
	}

	private static string Key(string name) => $"{AutoWrongCensusOptions.SectionName}:{name}";
}
"}

