{"path":"tools/LetUsCook.AutoWrongCensus/HostedServices/AutoWrongCensusHostedService.cs","i":"Writing hosted service","content":"using System.Diagnostics.CodeAnalysis;

using LetUsCook.AutoWrongCensus.Services;

using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace LetUsCook.AutoWrongCensus.HostedServices;

/// <summary>Runs the census and publishes the exit code; the host stops itself either way.</summary>
public sealed class AutoWrongCensusHostedService(
	IAutoWrongCensusRunner runner,
	IHostApplicationLifetime lifetime,
	ILogger<AutoWrongCensusHostedService> logger) : BackgroundService
{
	/// <summary>The process exit code: 0 success, 1 failure (fail-closed).</summary>
	public int ExitCode { get; private set; } = 1;

	/// <inheritdoc />
	[SuppressMessage("Design", "CA1031:Do not catch general exception types", Justification = "Top-level CLI host exception handler")]
	protected override async Task ExecuteAsync(CancellationToken stoppingToken)
	{
		try
		{
			ExitCode = await runner.RunAsync(stoppingToken).ConfigureAwait(false);
		}
		catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
		{
			ExitCode = 1;
		}
		catch (Exception ex)
		{
			logger.LogError(ex, "AutoWrongCensus runner failed.");
			ExitCode = 1;
		}
		finally
		{
			lifetime.StopApplication();
		}
	}
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/HostedServices/AutoWrongCensusHostBuilderFactory.cs","i":"Writing host factory","content":"using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;
using LetUsCook.Fdc.Lexicon;

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.HostedServices;

/// <summary>
/// Builds the census host graph. <see cref="AutoWrongCensusCli.RunAsync"/> and the tests must both go
/// through this factory, so the tested graph is the shipped one.
/// </summary>
public static class AutoWrongCensusHostBuilderFactory
{
	/// <summary>Creates the host application builder for one CLI invocation.</summary>
	/// <param name="args">The raw command-line arguments.</param>
	/// <param name="output">TSV sink; defaults to stdout.</param>
	/// <param name="error">Summary/diagnostics sink; defaults to stderr.</param>
	public static HostApplicationBuilder Create(
		string[] args,
		System.IO.TextWriter? output = null,
		System.IO.TextWriter? error = null)
	{
		var builder = Host.CreateApplicationBuilder(args);

		builder.Configuration.AddInMemoryCollection(CommandLineArgumentParser.Parse(args));
		builder.Services.Configure<AutoWrongCensusOptions>(builder.Configuration.GetSection(AutoWrongCensusOptions.SectionName));

		builder.Logging.ClearProviders();
		builder.Logging.AddConsole();
		builder.Logging.SetMinimumLevel(LogLevel.Error);
		builder.Logging.AddFilter("Microsoft", LogLevel.Warning);

		builder.Services.AddSingleton(new OutputSinks(output ?? System.Console.Out, error ?? System.Console.Error));
		builder.Services.AddSingleton<FdcNormalizer>();
		builder.Services.AddSingleton<Services.ExactOverrideKeyIndex>();
		builder.Services.AddSingleton<Services.AutoWrongClassifier>();
		builder.Services.AddSingleton<IAutoWrongCensusRunner, AutoWrongCensusRunner>();
		builder.Services.AddSingleton<AutoWrongCensusHostedService>();
		builder.Services.AddHostedService(sp => sp.GetRequiredService<AutoWrongCensusHostedService>());

		return builder;
	}
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","i":"Writing classifier","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines:
/// <see cref="Relation"/> (how the accepted row differs from the labelled row) and <see cref="Site"/>
/// (which decision path shipped it). Every comparison goes through the production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/> —
/// never a copy of that logic (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>A can or jar pack unit anywhere in the raw line.</summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Reusable single-token list for the per-token state checks (the runner is single-threaded).</summary>
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier over the production normalizer and the exact-overrides key index.</summary>
	/// <param name="normalizer">Production FDC normalizer.</param>
	/// <param name="overrideKeys">Keys of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one auto-wrong line. <see cref="ClassificationResult.Site"/> is null on an unknown path.</summary>
	/// <param name="line">The trace line (auto and wrong).</param>
	/// <returns>The relation, site and every recorded field for the TSV row.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var (site, overrideKey) = ClassifySite(atom, line.RawText);

		var relation = string.Empty;
		var missingField = string.Empty;
		var qualifierDiff = string.Empty;
		var tierDirection = string.Empty;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = Relations.NoLabel;
		}
		else
		{
			var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
			var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
			var keyState = CombinedState(keyTokens);
			var acceptedState = CombinedState(acceptedTokens);

			var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
			var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
				? new ParsedFdcDescription(string.Empty, [], null)
				: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

			var headKey = SingularPhrase(keyParsed.HeadTerm);
			var headAccepted = SingularPhrase(acceptedParsed.HeadTerm);
			var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
			var keyHeadPhrase = KeyHeadPhrase(keyTokens);

			if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
			{
				relation = Relations.PackUnitState;
			}
			else if (keyHeadPhrase.Count >= 2 && parsedName.Count == 1
				&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
			{
				relation = Relations.CompoundHeadLost;
			}
			else if (headKey.SequenceEqual(headAccepted, StringComparer.OrdinalIgnoreCase))
			{
				if (keyState != acceptedState)
				{
					relation = Relations.StateMismatch;
				}
				else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
				{
					// The brief's §8: a relation that needs a field the trace lacks is `other`, with the field named.
					relation = Relations.Other;
					missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				}
				else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
				{
					relation = Relations.RowChoiceTier;
					tierDirection = TierRank(keyTier) > TierRank(acceptedTier) ? "key higher" : "accepted higher";
				}
				else
				{
					relation = Relations.SameHeadOtherQualifier;
					qualifierDiff = QualifierDiff(keyParsed, acceptedParsed);
				}
			}
			else
			{
				relation = Relations.SiblingFood;
			}
		}

		return new ClassificationResult(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			site,
			overrideKey,
			acceptedTier,
			keyTier,
			CombinedState(_normalizer.NormalizeToTokens(acceptedDesc)),
			CombinedState(_normalizer.NormalizeToTokens(keyDesc)),
			atom?.ParsedName ?? string.Empty,
			string.Join(' ', KeyHeadPhrase(_normalizer.NormalizeToTokens(keyDesc))),
			acceptedDesc,
			keyDesc,
			line.RawText,
			missingField,
			qualifierDiff,
			tierDirection,
			atom);
	}

	/// <summary>
	/// The key's head phrase: the leading normalised tokens of the key description, cut before the first
	/// token production state extraction treats as a state word — <see cref="FdcLexicon.ModifierWords"/>
	/// (blanched, crushed, grated, …) or a token <see cref="FdcMatcher.ExtractCandidateState"/>/
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> reports on its own. "Bread, crumbs, dry, grated,
	/// plain" → [bread, crumbs]; "Nuts, almonds, blanched" → [nut, almond].
	/// </summary>
	/// <param name="tokens">Normalised key-description tokens.</param>
	/// <returns>The head-phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask of a description: <see cref="FdcMatcher.ExtractCandidateState"/> OR
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> on the normalised tokens — the same two calls
	/// <see cref="FdcMatcher"/> makes per candidate (FdcMatcher.cs:1155-1157).
	/// </summary>
	/// <param name="tokens">Normalised tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The resolver's own exact-phrase reuse verdict for a line's parsed name against the master slug it
	/// linked: <see cref="IngredientLineResolver.ShouldReuse"/> on <see cref="IngredientLineParser.ComputeSlug"/>
	/// of the parsed name. Census statistic only — it never changes the relation or the site.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The master slug the atom linked.</param>
	/// <returns>The production verdict, or null when there is nothing to compare.</returns>
	public static bool? ReuseRuleVerdict(string? parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return null;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	/// <summary>
	/// Whether the raw line's override-lookup form — cut at the first parenthesis, trimmed, lower-cased,
	/// the same cleaning <see cref="FdcMatcher.MatchAsync"/> applies before its raw-key lookup
	/// (FdcMatcher.cs:165-168; <c>StripFromParenthesis</c> is private, so the cut is applied here and
	/// documented in the report) — is a key of <c>exact-overrides.json</c>.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>True when the cleaned text is an exact-overrides key.</returns>
	public bool IsOverrideKey(string rawText)
	{
		var cleaned = rawText.Trim().ToLowerInvariant();
		var paren = cleaned.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			cleaned = cleaned[..paren].Trim();
		}

		return _overrideKeys.Contains(cleaned);
	}

	private (string? Site, string? OverrideKey) ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null || string.IsNullOrEmpty(atom.Path))
		{
			return (null, null);
		}

		switch (atom.Path)
		{
			case "override":
				return (Sites.Override, IsOverrideKey(rawText) ? "yes" : "no");
			case "curated":
				return (Sites.Curated, null);
			case "ranker":
				return (atom.Reused ? Sites.Reuse : Sites.Ranker, null);
			default:
				return (null, null);
		}
	}

	private string QualifierDiff(ParsedFdcDescription keyParsed, ParsedFdcDescription acceptedParsed)
	{
		var keyQualifiers = keyParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acceptedQualifiers = acceptedParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);

		var keyOnly = keyQualifiers.Where(q => !acceptedQualifiers.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase);
		var acceptedOnly = acceptedQualifiers.Where(q => !keyQualifiers.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase);

		return $"key+[{string.Join(' ', keyOnly)}] accepted+[{string.Join(' ', acceptedOnly)}]";
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlgacy" or "srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}

/// <summary>Relation axis values, in the brief's precedence order.</summary>
public static class Relations
{
	/// <summary>Expected label empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Raw line carries a can/jar unit; key state has Canned, accepted state does not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Key head phrase has 2+ words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Head terms agree after singularising; the combined state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Head terms and state agree; the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Head terms agree and nothing above holds; the qualifier sets differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Head terms differ after singularising.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Catch-all: a needed field is missing or no rule held.</summary>
	public const string Other = "other";
}

/// <summary>Site axis values.</summary>
public static class Sites
{
	/// <summary>Path ranker and the line reused an existing row/master.</summary>
	public const string Reuse = "reuse";

	/// <summary>Path override.</summary>
	public const string Override = "override";

	/// <summary>Path curated.</summary>
	public const string Curated = "curated";

	/// <summary>Path ranker, not reused.</summary>
	public const string Ranker = "ranker";
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/ExactOverrideKeyIndex.cs","i":"Writing override key index","content":"using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The raw-name key set of <c>Lexicon/Resources/exact-overrides.json</c> (embedded in the Fdc
/// assembly), for the <c>overrideKey</c> column: whether the normalised rawText is a key of the
/// override table. A key set, not matcher logic — the lookup itself is a plain dictionary hit.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the embedded exact-overrides table once.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		_keys = entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Number of keys in the table.</summary>
	public int Count => _keys.Count;

	/// <summary>Whether <paramref name="key"/> is a raw-name key of the table (case-insensitive).</summary>
	/// <param name="key">The normalised raw line text.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
"}

{"i":"Writing the relation/site classifier","path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — the relation between the
/// accepted row and the labelled (key) row, and the decision site. Every food-side judgement calls
/// the production helpers (F-428 D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>,
/// <see cref="IngredientLineResolver.ShouldReuse(string, string)"/> and
/// <see cref="IngredientLineResolver.SingularizeToken"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key row is <see cref="FoodState.Canned"/> and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the heads agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: the heads and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: the heads agree and nothing above holds.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the heads differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no rule held or a needed trace field was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path decided the line.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the line.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked a fresh row.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused for the single-token state probes below; the classifier is driven single-threaded by the runner.
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates the classifier over the production helpers.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one auto-wrong line. The caller filters on <c>auto &amp;&amp; !correct</c>.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, the site, and the audit fields for the TSV row.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var (site, overrideKey) = ClassifySite(line);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = Atom(line)?.ParsedName ?? string.Empty,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();
		result.KeyHead = string.Join(' ', KeyHeadPhrase(keyTokens));

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedName = SingularPhrase(Atom(line)?.ParsedName ?? string.Empty);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		// Rule 2 — a pack unit in the raw line, the key row is Canned, the accepted row is not.
		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = PackUnitState;
			return result;
		}

		// Rule 3 — the key head phrase is a compound and the parsed name kept only its first word.
		if (keyPhrase.Count >= 2
			&& parsedName.Count == 1
			&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (headsAgree)
		{
			// Rule 4 — the heads agree, the state masks differ.
			if (keyState != acceptedState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			// Rule 5 — the heads and state agree, the tier differs. A missing tier cannot be compared.
			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.Relation = Other;
				result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return result;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			// Rule 6 — heads, state and tier agree; record the qualifier difference.
			result.Relation = SameHeadOtherQualifier;
			(result.KeyOnlyQualifiers, result.AcceptedOnlyQualifiers) = QualifierDiffs(keyParsed.Qualifiers, acceptedParsed.Qualifiers);
			return result;
		}

		// Rule 7 — the heads differ.
		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to (excluding) the first token the
	/// production state machinery or the modifier lexicon treats as a state/modifier word. This is
	/// the head the relation rules compare against the parsed name — the parser's single-token
	/// <see cref="ParsedFdcDescription.HeadTerm"/> cannot see the <c>Bread, crumbs</c> shape, where the
	/// second segment names the food, not its state.
	/// </summary>
	/// <param name="keyTokens">The key row's normalized tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateOrModifier(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The state mask the matcher sees on a row: candidate state ∪ satisfiers (FdcMatcher.MatchAsync composes both).</summary>
	/// <param name="tokens">The row's normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the production ShouldReuse exact-phrase rule would match the line's parsed name to the
	/// linked master slug — the reuse-site audit in the stderr summary.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>Whether the production rule matches.</returns>
	public static bool ReuseRuleMatches(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	/// <summary>
	/// Folds raw line text the way the override lookup folds it before the raw-key table is consulted
	/// (FdcMatcher.MatchAsync: trim, lower-case, drop from the first parenthesis).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);

#pragma warning disable CA1308 // Reason: parity with FdcMatcher.MatchAsync's override-lookup folding.
		var lowered = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		var parenIndex = lowered.IndexOf('(', StringComparison.Ordinal);
		return (parenIndex >= 0 ? lowered[..parenIndex] : lowered).Trim();
	}

	private (string Site, string OverrideKey) ClassifySite(TraceLine line)
	{
		var atom = Atom(line);
		if (atom is null)
		{
			return (string.Empty, string.Empty);
		}

		switch (atom.Path)
		{
			case "override":
				var overrideKey = _overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no";
				return (SiteOverride, overrideKey);
			case "curated":
				return (SiteCurated, string.Empty);
			case "ranker":
				return (atom.Reused ? SiteReuse : SiteRanker, string.Empty);
			default:
				return (string.Empty, string.Empty);
		}
	}

	private static TraceAtom? Atom(TraceLine line) =>
		line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 ? values[0] : string.Empty;

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly) QualifierDiffs(
		IReadOnlyList<string> keyQualifiers,
		IReadOnlyList<string> acceptedQualifiers)
	{
		var keySet = new HashSet<string>(keyQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var keyOnly = keySet.Where(t => !acceptedSet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
		var acceptedOnly = acceptedSet.Where(t => !keySet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
		return (keyOnly, acceptedOnly);
	}

	private bool CarriesStateOrModifier(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
"}

{"i":"Rewriting classifier cleanly","path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the accepted row vs the key row
/// (<see cref="ClassificationResult.Relation"/>) and the decision site
/// (<see cref="ClassificationResult.Site"/>). Every relation test calls production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> — never a copy of matcher logic (D-014).
/// Not thread-safe: one <c>Classify</c> call at a time.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Raw-text can/jar unit token — the pack-unit shape in P12.13 brief §2.</summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;

	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks; ExtractCandidateState/Satisfiers only
	// read the list, so re-filling one cell per token is safe on this single-threaded runner and
	// keeps the census allocation-free (CA1861 forbids the constant-array argument form anyway).
	private readonly string[] _singleToken = new string[1];

	/// <summary>Creates the classifier over the production normalizer.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The shipped <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Site: the line reused an existing ingredient master/row.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the ranker picked a fresh row (not reused).</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Site: an override file resolved the line.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue resolved the line.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Relation: the line has no label.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: the label wants a canned row; the accepted row is not canned.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parser name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; qualifier tokens differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds (typically a missing trace field).</summary>
	public const string RelationOther = "other";

	/// <summary>Classifies one trace line. Only <c>auto &amp;&amp; !correct</c> lines are meant for this call.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and the recorded row facts.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = ChooseAtom(line);
		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var parsedNameTokens = SingularTokens(_normalizer.NormalizeToTokens(atom.ParsedName));

		var (relation, missingField, keyOnlyQualifiers, acceptedOnlyQualifiers) = ClassifyRelation(
			line, keyDesc, acceptedDesc, keyTier, acceptedTier, keyState, acceptedState, parsedNameTokens, keyHeadPhrase);

		var site = SiteOf(atom);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key's food-name head phrase: the description's normalized tokens up to the first token that
	/// production itself treats as state or preparation (<see cref="FdcLexicon.ModifierWords"/>, or
	/// <see cref="FdcMatcher.ExtractCandidateState"/> / <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// of that single token). This is the multi-word head the brief's relation 3 asks about —
	/// <c>"Bread, crumbs, dry, grated, plain"</c> → <c>bread crumbs</c>, because <c>dry</c> is the first
	/// production state token — while <c>"Tomatoes, crushed, canned"</c> stays single-word
	/// (<c>crushed</c> is a production modifier). The single-token
	/// <see cref="FdcDescriptionParser.Parse"/> <c>HeadTerm</c> cannot express the former.
	/// </summary>
	/// <param name="normalizedKeyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens, singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> normalizedKeyTokens)
	{
		ArgumentNullException.ThrowIfNull(normalizedKeyTokens);

		var phrase = new List<string>(normalizedKeyTokens.Count);
		foreach (var token in normalizedKeyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// Folds a raw line text the way production's override lookup does
	/// (<c>FdcMatcher.StripFromParenthesis</c> + lower-case + trim — private there, so the one-step
	/// fold is applied here against the shipped key set; named in the report per brief §8).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded text for the <c>exact-overrides.json</c> key lookup.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		return (cut >= 0 ? rawText[..cut] : rawText).Trim().ToLowerInvariant();
	}

	private (string Relation, string? MissingField, IReadOnlyList<string>? KeyOnly, IReadOnlyList<string>? AcceptedOnly) ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return (RelationNoLabel, "expectedDescriptions", null, null);
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return (RelationPackUnitState, null, null, null);
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], keyHeadPhrase[0], StringComparison.OrdinalIgnoreCase))
		{
			return (RelationCompoundHeadLost, null, null, null);
		}

		var headKey = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm;
		var headAccepted = string.IsNullOrWhiteSpace(acceptedDesc)
			? string.Empty
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm;
		if (!HeadsAgree(headKey, headAccepted))
		{
			return (RelationSiblingFood, null, null, null);
		}

		if (keyState != acceptedState)
		{
			return (RelationStateMismatch, null, null, null);
		}

		if (string.IsNullOrEmpty(acceptedTier) || string.IsNullOrEmpty(keyTier))
		{
			return (RelationOther, string.IsNullOrEmpty(acceptedTier) ? "actualDataTypes" : "expectedDataTypes", null, null);
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return (RelationRowChoiceTier, null, null, null);
		}

		var keyQualifiers = QualifierSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedQualifiers = QualifierSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
		return (RelationSameHeadOtherQualifier, null, keyQualifiers.Except(acceptedQualifiers).ToArray(), acceptedQualifiers.Except(keyQualifiers).ToArray());
	}

	private bool HeadsAgree(string headKey, string headAccepted)
	{
		var keyTokens = SingularTokens(_normalizer.NormalizeToTokens(headKey));
		var acceptedTokens = SingularTokens(_normalizer.NormalizeToTokens(headAccepted));
		return keyTokens.SequenceEqual(acceptedTokens, StringComparer.OrdinalIgnoreCase);
	}

	private static HashSet<string> QualifierSet(IReadOnlyList<string> qualifiers) =>
		new(qualifiers.Select(t => IngredientLineResolver.SingularizeToken(t.ToLowerInvariant())), StringComparer.OrdinalIgnoreCase);

	private FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private bool CarriesStateToken(string token)
	{
		_singleToken[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static TraceAtom ChooseAtom(TraceLine line)
	{
		if (line.Atoms.Count == 0)
		{
			throw new InvalidOperationException($"Trace line {line.HoldoutId}#{line.LineIndex} has no atoms; cannot determine the decision site.");
		}

		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms[0];
	}

	private static string SiteOf(TraceAtom atom) => atom.Path.ToLowerInvariant() switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => atom.Reused ? SiteReuse : SiteRanker,
		_ => string.Empty,
	};

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static IReadOnlyList<string> SingularTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));
}
"}

