{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusRunner.cs","i":"Writing runner","content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: reads one HoldoutGate trace (debug/batch only — D-029), classifies every
/// <c>auto &amp;&amp; !correct</c> line with <see cref="AutoWrongClassifier"/> and writes the TSV to
/// <see cref="CensusOutputWriters.Output"/> and the relation × site summary to
/// <see cref="CensusOutputWriters.Error"/>.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunnerOptions options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	CensusOutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\t" +
		"acceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = options.Value;
		if (string.IsNullOrEmpty(options.Command))
		{
			writers.Error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			AutoWrongCensusUsage.Print();
			return 1;
		}

		if (!File.Exists(options.TracePath))
		{
			writers.Error.WriteLine($"trace file not found at '{options.TracePath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refusedSet = lines.Select(l => l.Set).Where(s => s is not ("debug" or "batch")).Distinct().OrderBy(s => s, StringComparer.Ordinal).FirstOrDefault();
		if (refusedSet is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{refusedSet}' is not debug or batch (D-029: no sealed read).");
			return 1;
		}

		if (options.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false);
		}

		return await RunCensusAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private async Task<int> RunCensusAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var results = new List<ClassificationResult>(lines.Count);
		var unknownSite = false;

		foreach (var line in lines)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite = true;
				writers.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "-"}' on {line.HoldoutId}#{line.LineIndex}; cannot classify the site.");
			}

			results.Add(result);
		}

		writers.Output.WriteLine(CensusHeader);
		foreach (var result in results)
		{
			writers.Output.WriteLine(
				$"{result.HoldoutId}\t{result.LineIndex}\t{result.Set}\t{result.Relation}\t{result.Site}\t{result.OverrideKey}\t" +
				$"{result.AcceptedTier}\t{result.KeyTier}\t{result.AcceptedState}\t{result.KeyState}\t{result.ParsedName}\t{result.KeyHead}\t" +
				$"{Sanitize(result.AcceptedDesc)}\t{Sanitize(result.KeyDesc)}\t{Sanitize(result.RawText)}");
		}

		WriteSummary(writers.Error, results);

		await Task.CompletedTask.ConfigureAwait(false);
		return unknownSite ? 1 : 0;
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var options = options.Value;
		if (!File.Exists(options.CensusTsvPath))
		{
			writers.Error.WriteLine($"census TSV not found at '{options.CensusTsvPath}'.");
			return 1;
		}

		var windowRows = ReadWindowRows(options.CensusTsvPath);
		if (windowRows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex), StringComparer.Ordinal, StringComparer.Ordinal);
		var missing = 0;

		writers.Output.WriteLine(PairsHeader);
		foreach (var (holdoutId, lineIndex) in windowRows)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				continue;
			}

			var parsedName = line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty;
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var parsedNameHead = string.Join(' ', Fold(normalizer.NormalizeToTokens(parsedName)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(keyDesc)));

			writers.Output.WriteLine($"{holdoutId}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
		}

		writers.Error.WriteLine($"pairs: {windowRows.Count} window rows (blocker=window, route in {{compound, other}}), {missing} not found in the trace.");
		await Task.CompletedTask.ConfigureAwait(false);
		return 0;
	}

	private static IReadOnlyList<(string HoldoutId, int LineIndex)>? ReadWindowRows(string path)
	{
		var header = File.ReadLines(path).First().Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf[header[i]] = i;
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				return null;
			}
		}

		var rows = new List<(string, int)>();
		foreach (var line in File.ReadLines(path).Skip(1))
		{
			if (line.Length == 0)
			{
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length < header.Length || cells[indexOf["blocker"]] != "window" ||
				(cells[indexOf["route"]] != "compound" && cells[indexOf["route"]] != "other"))
			{
				continue;
			}

			rows.Add((cells[indexOf["holdoutId"]], int.Parse(cells[indexOf["lineIndex"]], CultureInfo.InvariantCulture)));
		}

		return rows;
	}

	private static void WriteSummary(TextWriter error, IReadOnlyList<ClassificationResult> results)
	{
		var sets = string.Join(",", results.Select(r => r.Set).Distinct().OrderBy(s => s, StringComparer.Ordinal));
		error.WriteLine($"autoWrongCensus set={sets} autoWrongLines={results.Count}");

		foreach (var (relation, site, count) in results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal))
		{
			error.WriteLine($"relation={relation}\tsite={site}\tcount={count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):0.0}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		error.WriteLine(missing.Any() ? $"missingFields: {string.Join(" ", missing)}" : "missingFields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			error.WriteLine($"row-choice-tier: keyHigher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} acceptedHigher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> Fold(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Sanitize(string value)
	{
		if (value.IndexOf('\t') < 0 && value.IndexOf('\n') < 0 && value.IndexOf('\r') < 0)
		{
			return value;
		}

		return value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			if (raw.Length == 0)
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"refused: malformed trace line in '{path}': {ex.Message}");
				return null;
			}
		}

		return lines;
	}
}

